c \u0645\u0639 \u062a\u0628\u062f\u064a\u0644 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0645\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u0637\u0639\u0646\u0627\u062a \u0648\u0627\u0644\u0642\u0641\u0632\u0627\u062a \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3582","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3582-PM1PZjg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3582-PM1PZjg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d812fb29-6c86-539d-8770-c66607003237","source_id":"1688","name_en":"lunge with twist","name_ar":"\u0627\u0646\u062f\u0641\u0639 \u0645\u0639 \u062a\u0637\u0648\u0631","match_names":["lunge with twist"],"muscle":"core","equipment":"bodyweight","aliases":["lunge with twist"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart.\nTake a step forward with your right foot, lowering your body into a lunge position.\nAs you lunge, twist your torso to the right, bringing your left elbow towards your right knee.\nPause for a moment, then return to the starting position.\nRepeat on the other side, stepping forward with your left foot and twisting your torso to the left.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0646\u062f\u0641\u0627\u0639\u0643\u060c \u0642\u0645 \u0628\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u062c\u0644\u0628 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631\u060c \u0645\u0639 \u0627\u0644\u062a\u0642\u062f\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1688","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["quadriceps","glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1688-K9VL0Jq.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1688-K9VL0Jq.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a67e2ad5-cebb-59f3-8c70-5a11724cc790","source_id":"0613","name_en":"lying (side) quads stretch","name_ar":"\u0627\u0644\u0643\u0630\u0628 (\u0627\u0644\u062c\u0627\u0646\u0628) \u062a\u0645\u062a\u062f \u0627\u0644\u0643\u0648\u0627\u062f","match_names":["lying (side) quads stretch"],"muscle":"quads","equipment":"bodyweight","aliases":["lying (side) quads stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your side with your legs straight.\nBend your top leg and grab your ankle or foot with your hand.\nGently pull your ankle or foot towards your glutes until you feel a stretch in your quads.\nHold the stretch for 20-30 seconds.\nRelease the stretch and repeat on the other side.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u062b\u0646\u0650 \u0633\u0627\u0642\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u0629 \u0648\u0623\u0645\u0633\u0643 \u0643\u0627\u062d\u0644\u0643 \u0623\u0648 \u0642\u062f\u0645\u0643 \u0628\u064a\u062f\u0643.\n\u0627\u0633\u062d\u0628 \u0643\u0627\u062d\u0644\u0643 \u0623\u0648 \u0642\u062f\u0645\u0643 \u0628\u0644\u0637\u0641 \u0646\u062d\u0648 \u0623\u0631\u062f\u0627\u0641\u0643 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0636\u0644\u0627\u062a\u0643 \u0627\u0644\u0631\u0628\u0627\u0639\u064a\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0613","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0613-BWnJR72.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0613-BWnJR72.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"847b0695-e401-5ca9-80fa-412e7dc70fea","source_id":"2312","name_en":"lying elbow to knee","name_ar":"\u0627\u0644\u0643\u0630\u0628 \u0627\u0644\u0643\u0648\u0639 \u0625\u0644\u0649 \u0627\u0644\u0631\u0643\u0628\u0629","match_names":["lying elbow to knee"],"muscle":"core","equipment":"bodyweight","aliases":["lying elbow to knee"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.\nAt the same time, extend your right leg straight out and lift it off the ground.\nPause for a moment, then return to the starting position.\nRepeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0648\u0636\u0639 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647\u060c \u0645\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0627\u0631\u0641\u0639\u0647\u0627 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629 \u0642\u0645 \u0628\u062c\u0644\u0628 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0645\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2312","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2312-AQIhRjM.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efa