u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0620","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0620-WhuFnR7.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0620-WhuFnR7.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e60d9c57-22f3-5bf5-8cea-9c14fc6dfb48","source_id":"0865","name_en":"lying leg-hip raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0648\u0627\u0644\u0648\u0631\u0643 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621","match_names":["lying leg-hip raise"],"muscle":"core","equipment":"bodyweight","aliases":["lying leg-hip raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your legs extended and your arms by your sides.\nPlace your hands under your glutes for support.\nEngage your core and lift your legs off the ground, raising them towards the ceiling.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062a\u062d\u062a \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0631\u0641\u0639\u0647\u0645\u0627 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0865","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0865-9IxJdtC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0865-9IxJdtC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7d56e38c-7b5d-509d-876d-272e7b40598a","source_id":"1301","name_en":"machine inner chest press","name_ar":"\u0622\u0644\u0629 \u0636\u063a\u0637 \u0627\u0644\u0635\u062f\u0631 \u0627\u0644\u062f\u0627\u062e\u0644\u064a","match_names":["machine inner chest press"],"muscle":"chest","equipment":"machine","aliases":["machine inner chest press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and position yourself on the machine with your back flat against the pad.\nGrasp the handles with an overhand grip and position your elbows at a 90-degree angle.\nPush the handles forward until your arms are fully extended, exhaling during the movement.\nPause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u062b\u0645 \u0636\u0639 \u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0638\u0647\u0631\u0643 \u0645\u0633\u0637\u062d\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629 \u0648\u0636\u0639 \u0645\u0631\u0641\u0642\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0627\u062f\u0641\u0639 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0627\u062a \u0639\u0646\u062f \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u0627\u0633\u062a\u0646\u0634\u0627\u0642 \u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u0630\u0644\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1301","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1301-wDN97Ca.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1301-wDN97Ca.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"81281cb1-d747-50bf-8ed4-1b3683de94cd","source_id":"0624","name_en":"march sit (wall)","name_ar":"\u0627\u0639\u062a\u0635\u0627\u0645 \u0627\u0644\u0645\u0633\u064a\u0631\u0629 (\u0627\u0644\u062c\u062f\u0627\u0631)","match_names":["march sit (wall)"],"muscle":"glutes","equipment":"bodyweight","aliases":["march sit (wall)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your back against a wall and your feet hip-width apart.\nSlowly slide your back down the wall until your knees are bent at a 90-degree angle.\nLift your right foot off the ground and bring your knee towards your chest.\nLower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.\nContinue alternating between lifting your right and left foot for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u062d\u0631\u0643 \u0638\u0647\u0631\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644 \u0627\u0644\u062d\u0627\u0626\u0637 \u062d\u062a\u0649 \u062a\u0646\u062d\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0627\u0631\u0641\u0639\u064a \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u062d\u0636\u0631\u064a \u0631\u0643\u0628\u062a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0628\u062d\u064a\u062b \u062a\u0635\u0644 \u0631\u0643\u0628\u062a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0631\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u06