ed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"30bbcc12-c631-5108-8b76-3b32776f5831","source_id":"0636","name_en":"olympic barbell hammer curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0648\u0644\u0645\u0628\u064a\u0629","match_names":["olympic barbell hammer curl"],"muscle":"biceps","equipment":"olympic_barbell","aliases":["olympic barbell hammer curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.\nLet the barbell hang at arm''s length in front of your thighs, with your palms facing your body.\nKeeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the barbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u0623\u0648\u0644\u0645\u0628\u064a \u0628\u0642\u0628\u0636\u0629 \u064a\u062f.\n\u062f\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u064a\u062a\u062f\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0630\u0631\u0627\u0639 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0636","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_s