27\u0644\u0629 \u062d\u0648\u0636\u0643 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u062d\u0627\u0641\u0638\u064a \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0639\u0644\u0649 \u0642\u0628\u0636 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643.\n\u062d\u0631\u0631 \u0627\u0644\u0645\u064a\u0644 \u0648\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3147","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3147-NKJ8o6x.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3147-NKJ8o6x.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"70a75004-7edf-582c-8bc7-307e8108f778","source_id":"1422","name_en":"pelvic tilt into bridge","name_ar":"\u0625\u0645\u0627\u0644\u0629 \u0627\u0644\u062d\u0648\u0636 \u0625\u0644\u0649 \u0627\u0644\u062c\u0633\u0631","match_names":["pelvic tilt into bridge"],"muscle":"glutes","equipment":"bodyweight","aliases":["pelvic tilt into bridge"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your back with your knees bent and feet flat on the ground.\nPlace your arms by your sides with your palms facing down.\nEngage your glutes and core muscles.\nTilt your pelvis upward, lifting your hips off the ground.\nHold the bridge position for a few seconds.\nSlowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0623\u0644\u0648\u064a\u0629 \u0648\u0627\u0644\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629.\n\u0642\u0645 \u0628\u0625\u0645\u0627\u0644\u0629 \u062d\u0648\u0636\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0634\u063a\u0644 \u0648\u0636\u0639 \u0627\u0644\u062c\u0633\u0631 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1422","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1422-D9qe7CM.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1422-D9qe7CM.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"86cc7703-69b0-5a3a-8563-99bae78638b7","source_id":"1388","name_en":"peroneals stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0634\u0638\u0648\u064a\u0629","match_names":["peroneals stretch"],"muscle":"calves","equipment":"rope","aliases":["peroneals stretch"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Sit on the ground with your legs extended in front of you.\nLoop the rope around the ball of your foot and hold the ends of the rope with your hands.\nGently pull the rope towards you, flexing your foot and stretching your calf muscles.\nHold the stretch for 15-30 seconds.\nRelease the tension on the rope and repeat the stretch on the other leg.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643.\n\u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u062d\u0628\u0644 \u062d\u0648\u0644 \u0643\u0631\u0629 \u0642\u062f\u0645\u0643 \u0648\u0623\u0645\u0633\u0643 \u0637\u0631\u0641\u064a \u0627\u0644\u062d\u0628\u0644 \u0628\u064a\u062f\u064a\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0646\u062d\u0648\u0643 \u0628\u0644\u0637\u0641\u060c \u0645\u0639 \u062b\u0646\u064a \u0642\u062f\u0645\u0643 \u0648\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0633\u0627\u0642.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0627\u0644\u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0627\u0644\u062d\u0628\u0644 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1388","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["ankles","feet"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1388-XhfS1DZ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1388-XhfS1DZ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9d54bf16-8e6f-5613-8c65-46c1069e3db7","source_id":"3662","name_en":"pike-to-cobra push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0645\u0646 \u0628\u0627\u064a\u0643 \u0625\u0644\u0649 \u0643\u0648\u0628\u0631\u0627","match_names":["pike-to-cobra push-up"],"muscle":"glutes","equipment":"bodyweight","aliases":["pike-to-cobra push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\nEngage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.\nLower your upper body towards the ground by bending your elbows, keeping them close to your body.\nAs you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.\nReverse the movement by bending your elbows and lowering your chest back down towards the ground.\nPush through your hands to return to the inverted V position.\nContinue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641\u060c \u0644\u062a\u0643\u0648\u064a\u0646 \u0634\u0643\u0644 V \u0645\u0642\u0644\u0648\u0628 \u0628\u062c\u0633\u0645\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0625\u0646\u0632\u0627\u0644\u0643 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0642\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u0648\u0632\u0646\u0643 \u0644\u0644\u0623\u0645\u0627\u0645 \u0648\u0627\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0643\u0648\u0628\u0631\u0627 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0631\u0641\u0639 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 V \u0627\u0644\u0645\u0642\u0644\u0648\u0628.\n\u0648\u0627\u0635\u0644 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0623\u0648\u0644\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3662","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["core","shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3662-XPUDTt7.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3662-XPUDTt7.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c276e9b8-fbac-5400-8232-65335e9e2762","source_id":"1306","name_en":"plyo push up","name_ar":"\u0627\u062f\u0641\u0639 plyo \u0644\u0623\u0639\u0644\u0649","match_names":["plyo push up"],"muscle":"chest","equipment":"bodyweight","aliases":["plyo push up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start in a high plank position with your hands slightly wider than shoulder-width apart.\nLower your chest towards the ground by bending your elbows, keeping your body in a straight line.\nPush explosively off the ground, using your chest muscles to propel your upper body off the ground.\nLand softly with your hands back in the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062e\u0641\u0636\u064a \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u062f\u0641\u0639 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0644\u062f\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0645\u0639 \u0625\u0639\u0627\u062f\u0629 \u064a\u062f\u064a\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1306","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1306-Snj1wSv.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1306-Snj1wSv.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"af8be1d6-3bc8-597e-8d99-c2f9f393fdc6","source_id":"1687","name_en":"posterior step to overhead reach","name_ar":"\u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0646\u0641\u0642\u0627\u062a \u0627\u0644\u0639\u0627\u0645\u0629","match_names":["posterior step to overhead reach"],"muscle":"core","equipment":"bodyweight","aliases":["posterior step to overhead reach"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet hip-width apart and your arms by your sides.\nTake a step back with your right foot, landing on the ball of your foot.\nBend your left knee and lower your body into a lunge position.\nAs you lower into the lunge, simultaneously reach your arms overhead.\nPause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.\nRepeat the movement on the other side, stepping back with your left foot and bending your right knee.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u062e\u0630 \u062e\u0637\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0648\u0631\u0627\u0621 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0647\u0628\u0637 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639\u060c \u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0630\u0631\u0627\u0639\u064a\u0643 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0648\u062a\u0642\u062f\u064a\u0645 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1687","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["glutes","hamstrings","quadriceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1687-ErqK3UL.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1687-ErqK3UL.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
